      from c2 c left join e2 e on e.hkey = c.hkey
     group by c.hkey, c.CITY
    union all
    select 'COUNTRY_NAME' as column_name, c.hkey, c.COUNTRY_NAME as sat_value,
           max(iff(equal_null(c.COUNTRY_NAME, e.COUNTRY_NAME), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.COUNTRY_NAME) as src_value
      from c2 c left join e2 e on e.hkey = c.hkey
     group by c.hkey, c.COUNTRY_NAME
    union all
    select 'POSTAL_CODE' as column_name, c.hkey, c.POSTAL_CODE as sat_value,
           max(iff(equal_null(c.POSTAL_CODE, e.POSTAL_CODE), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.POSTAL_CODE) as src_value
      from c2 c left join e2 e on e.hkey = c.hkey
     group by c.hkey, c.POSTAL_CODE
    union all
    select 'STATE_NAME' as column_name, c.hkey, c.STATE_NAME as sat_value,
           max(iff(equal_null(c.STATE_NAME, e.STATE_NAME), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.STATE_NAME) as src_value
      from c2 c left join e2 e on e.hkey = c.hkey
     group by c.hkey, c.STATE_NAME
    union all
    select 'STREET_NAME' as column_name, c.hkey, c.STREET_NAME as sat_value,
           max(iff(equal_null(c.STREET_NAME, e.STREET_NAME), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.STREET_NAME) as src_value
      from c2 c left join e2 e on e.hkey = c.hkey
     group by c.hkey, c.STREET_NAME
