           max(iff(equal_null(c.ALTITUDE_LIMIT, e.ALTITUDE_LIMIT), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.ALTITUDE_LIMIT) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.ALTITUDE_LIMIT
    union all
    select 'MODE_OF_TRANSPORT' as column_name, c.hkey, c.MODE_OF_TRANSPORT as sat_value,
           max(iff(equal_null(c.MODE_OF_TRANSPORT, e.MODE_OF_TRANSPORT), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.MODE_OF_TRANSPORT) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.MODE_OF_TRANSPORT
)
select 'OPUS' as project, 'SAT_AUG_RISK_PERSON_TRAVEL' as satellite, 'OPUS_BJAZ_TRV_LOADER_DATA_MV' as record_source, column_name,
       count(*) as keys_compared,
       count_if(src_rows > 0 and matched = 1) as matched,
       count_if(src_rows > 0 and matched = 0) as mismatched,
       count_if(src_rows = 0) as no_source_row,
       array_slice(array_agg(iff(src_rows > 0 and matched = 0, object_construct('hkey', to_varchar(hkey, 'HEX'), 'sat', sat_value, 'src', src_value), null))
                   within group (order by hkey), 0, 3) as mismatch_examples,
       iff(mismatched = 0 and no_source_row = 0, 'PASS', 'FAIL') as status
